fn reverse(a: Vec<char>) -> Vec<char> {
    // Produce a new vector; do not modify `a`.
    // Using iter().rev() avoids index arithmetic and underflow risks.
    let mut b = Vec::with_capacity(a.len());
    for &ch in a.iter().rev() {
        b.push(ch);
    }
    b
}

